#define PI 3.1415926535897932384626433832795
#define t iTime 


vec3 shade( float r, vec2 center, vec2 pos, vec3 light )
{
    float z = sqrt(r*r - pos.x*pos.x -pos.y*pos.y);
    vec3 n = normalize(vec3(pos.x,pos.y,z));

    vec3 diffuseColor = vec3(0.4, 0.0, 0.6);				    
    vec3 specColor = vec3(1.0,1.0,1.0);	
    vec3 lightColor = vec3(1.0,1.0,1.0);

    float lissage = 15.0; 								

    vec3 diff = diffuseColor / PI; 						
    vec3 spec = specColor * ((lissage + 8.0) / (8.0 * PI));


    vec3 h = normalize(light + n); 

    float cosTi = max(dot(n, light), 0.0);
    float cosTh = max(dot(n, h), 0.0);

    vec3 diffuse = diff * lightColor * cosTi;  
    vec3 specular = spec * lightColor * pow(cosTh, lissage);


    vec3 rad = diffuse + specular; 

    return rad; 

}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
	vec2 center = iResolution.xy / 2.0;
	float r = iResolution.y / 2.2;
	vec2 pos = fragCoord.xy - center;

    vec2 uv = fragCoord.xy / iResolution.xy;

    vec3 colorStart = vec3(1.0, 0.0, 1.0);  
    vec3 colorEnd = vec3(0.0, 1.0, 1.0);    

    float oscillation = sin(t);  
    vec3 backgroundColor = mix(colorStart, colorEnd, (oscillation + 1.0) * 0.5); 

     if (length(pos) <= r) {
        vec3 light = normalize(vec3(sin(t), sin(t), cos(t)));
        vec3 rad = shade(r, center, pos, light);

        fragColor = vec4(rad, 1.0); 
    } else {
        fragColor = vec4(backgroundColor, 1.0);
    }

}
